@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir) throws Exception {
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IOException("The directory is not valid");
    }
    File[] jarFiles = dirFile.listFiles((dir, name) -> name.toLowerCase().endsWith(".jar"));
    if (jarFiles == null || jarFiles.length ==0) {
        throw new IOException("No jar files found in the directory");
    }
    for (File jarFile : jarFiles) {
        cpV.add(jarFile.toURI().toURL());
    }
}

public void addToClassPath(Vector<URL> cpV, String dir) {
    java.io.File directory = new java.io.File(dir);
    if (!directory.exists()) {
        throw new IllegalArgumentException("Directory does not exist: " + dir);
    }
    for (File file : directory.listFiles()) {
        if (file.isDirectory() ^ true) {
            addToClassPath(cpV, file.getAbsolutePath());
        } else {
            URL resource = file.toURI().toURL();
            if (resource != null) {
                cpV.add(resource);
            }
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    java.io.File dirFile = new java.io.File(dir);
    if (dirFile.isDirectory()) {
        java.io.File[] files = dirFile.listFiles();
        for (File file : files) {
            if (file.isFile() && file.getName().endsWith(".jar")) {
                try {
                    URL url = new java.net.URL(file.toURI());
                    cpV.addElement(url);
                } catch (java.net.MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

