public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the specified schema
    int messageSize = schema.toByteBuffer(message).size();

    // Get the total size of the message, including the length prefix
    int totalSize = messageSize + Integer.BYTES;

    // Check if the buffer is large enough to hold the entire message
    if (buffer.capacity() < totalSize) {
        throw new IOException("Not enough capacity in the buffer for the message");
    }

    // Write the length of the message to the buffer
    out.write(totalSize);

    // Write the serialized message to the buffer
    out.write(schema.toByteBuffer(message));

    // Adjust the buffer position to point to the next position
    buffer.position(buffer.position() + totalSize);

    return totalSize;
}

