protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Calculate the duration of each range
    long rangeLength = end - start;
    // Check if the range length is greater than the FETCH_DATA_DURATION
    if (rangeLength > FETCH_DATA_DURATION) {
        // Split the ranges according to the FETCH_DATA_DURATION
        int numRanges = (int) Math.ceil(rangeLength / FETCH_DATA_DURATION);
        List<TimeRange> timeRanges = new ArrayList<>();
        for (int i = 0; i < numRanges; i++) {
            long newStart = i * FETCH_DATA_DURATION + start;
            // Ensure that the new start time is less than or equal to the end time
            if (newStart <= end) {
                long newEnd = Math.min(newStart + FETCH_DATA_DURATION - 1, end);
                timeRanges.add(new TimeRange(newStart, newEnd));
            } else {
                // If the new start time exceeds the end time, add the last full range
                timeRanges.add(new TimeRange(start, end));
                break;
            }
        }
        return timeRanges;
    } else {
        // If the range length is less than or equal to FETCH_DATA_DURATION, return the original range
        return Collections.singletonList(new TimeRange(start, end));
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    TimeRangeBuilder builder = new TimeRangeBuilder();
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        long halfDuration = duration / 2;
        long newStart = start + halfDuration;
        long newEnd = end - halfDuration;
        list.add(builder.interval(newStart, newEnd));
        list.add(builder.interval(newStart, newEnd));
    }
    list.add(builder.interval(start, end));
    return list;
}

public class TimeRangeBuilder {

   private static final int FETCH_DATA_DURATION = 10000; // Example duration in milliseconds

   /**
    * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
    *
    * @param start The start time of the interval
    * @param end   The end time of the interval
    * @return A list of bounded time ranges
    */
   protected List<TimeRange> buildTimeRanges(long start, long end) {
       List<TimeRange> timeRanges = new ArrayList<>();

       // Calculate the minimum interval size
       long intervalSize = Math.min(FETCH_DATA_DURATION, end - start);

       // Calculate the number of time intervals
       int numIntervals = (int) Math.ceil((end - start) / intervalSize);

       // Generate the time ranges
       for (int i = 0; i < numIntervals; i++) {
           long startRange = start + i * intervalSize;
           long endRange = Math.min(start + (i + 1) * intervalSize, end);
           if (startRange < endRange) {
               timeRanges.add(new TimeRange(startRange, endRange));
           }
       }

       return timeRanges;
   }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // If start or end exceeds the fetch data duration, split the time range
    if (end - start > FETCH_DATA_DURATION) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        while (currentStart < end) {
            long rangeDuration = Math.min(FETCH_DATA_DURATION, end - currentStart);
            timeRanges.add(new TimeRange(currentStart, currentStart + rangeDuration - 1));
            currentStart += rangeDuration;
        }
        return timeRanges;
    } else {
        return Collections.singletonList(new TimeRange(start, end));
    }
}

