public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1 || dayStep > 30) {
        throw new IllegalArgumentException("dayStep must be between 1 and 30");
    }

    int newMonth = (int) (timeBucket / (1000 * 60 * 60 * 24 * dayStep)) % 12 + 1;
    int newYear = (int) (timeBucket / (1000 * 60 * 60 * 24 * dayStep * 12)) + 2000;
    return newYear * 10000 + newMonth * 100 + newDay;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 0) {
        throw new IllegalArgumentException("Day step must be non-negative");
    }
    long now = timeBucket;
    long result = timeBucket;
    if (dayStep == 0) {
        return now;
    }
    while (true) {
        now = (now - 1) / dayStep;
        if (now <= 0) {
            break;
        }
        result = (result - 1) / dayStep;
    }
    return result * dayStep + 1;
}

