public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        if ((str.charAt(i) & 0xE0) == 0xE0) {
            size += 2; // 3 bytes
        } else if ((str.charAt(i) & 0xC0) == 0xC0) {
            size += 1; // 2 bytes
        } else {
            size++; // 1 byte
        }
    }
    return size;
