public static int computeUTF8Size(CharSequence str, int index, int len) {
        int size = 0;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if ((c & 0x80) == 0) {
                size++; // 1 byte character
            } else if ((c & 0xC0) == 0xC0) {
                size += 2; // 2 byte character
            } else if ((c & 0xE0) == 0xE0) {
                size += 3; // 3 byte character
            } else if ((c & 0xF0) == 0xF0) {
                size += 4; // 4 byte character
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 character: " + c);
            }
        }
        return size;
    }

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int size = 0;
    final int strLen = str.length();
    for (int i = index; i < index + len; i++) {
        int ch = str.charAt(i);
        size++;
        if ((ch & 0xc0) == 0x80) { // Is a continuation byte
            size--;
        } else if ((ch & 0xe0) == 0xc0) { // Is a high byte of a two-byte character
            size--;
        } else if ((ch & 0xf0) == 0xc0) { // Is a high byte of a three-byte character
            size--;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int size = 0;
    int i = index;
    while (i < index + len) {
        int c = (char) str.charAt(i++);
        if((c & 0x80) == 0) {
            size += 1;
        } else if((c & 0xE0) == 0xC0) {
            size += 2;
        } else if((c & 0xF0) == 0xE0) {
            size += 3;
        }
    }
    return size;
}

