@Override
public void write(final byte b[],final int off,final int len) throws IOException {
    if (off < 0) {
        throw new IndexOutOfBoundsException("offset: " + off);
    }
    if (len < 0) {
        throw new IllegalArgumentException("length " + len);
    }
    if (off + len > b.length) {
        throw new IndexOutOfBoundsException("length: " + length + ", array length: " + b.length);
    }

    for (int i = off; i < off + len; i++) {
        this.buffer[this.nextIndex] = b[i];
        this.nextIndex = (this.nextIndex + 1) % this.buffer.length;
        if (this.nextIndex == this.startIndex) {
            this.flush();
        }
    }
}

