}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint along the x-axis
    double midPoint = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

    // Create two new boxes: the first half with the same y and width, and the second half with the same y but a different width
    Box2D half1 = new Box2D(midPoint, box.getMinY(), box.getWidth() / 2, box.getHeight());
    Box2D half2 = new Box2D(box.getMinX(), box.getMinY(), box.getWidth() / 2, box.getHeight());

    // Return a pair containing the two halves
    return Pair.create(half1, half2);
}

