public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return str;
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\' && i + 1 < str.length()) {
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case '\\' -> sb.append(ch);
                case 'n' -> sb.append('\n');
                case 'r' -> sb.append('\r');
                case 't' -> sb.append('\t');
                case 'b' -> sb.append('\b');
                case 'f' -> sb.append('\f');
                case 'u' -> {
                    if (i + 4 >= str.length()) {
                        throw new IllegalStateException("Invalid escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    char unicodeChar = (char) Integer.parseInt(hex, 16);
                    sb.append(unicodeChar);
                    i += 4; // Skip the 5 characters
                }
                default -> throw new IllegalStateException("Unsupported escape sequence");
            }
            i++; // Move to the next character after the escape sequence
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

