            if (b == '\\') {
                i++;
                if (i < bytesRead) {
                    b = (char) utf8Bytes[i];
                    if (b == 'u') {
                        i++;
                        String hex = Integer.toHexString(utf8Bytes[i]);
                        hex += Integer.toHexString(utf8Bytes[i + 1]);
                        hex += Integer.toHexString(utf8Bytes[i + 2]);
                        hex += Integer.toHexString(utf8Bytes[i + 3]);
                        charsetIndex = i + 4;
                        break;
                    }
                }
            }
            charBuffer[charsetIndex++] = b;
        }
    }
    fis.close();
    return new String(charBuffer, 0, charsetIndex);
}

