    // If the node has a previous node, update its next pointer to indicate the node is disconnected
    if (node.getNext() != null) {
        node.getNext().setPrevious(null);
    }

    // If the node has a next node, update its previous pointer to indicate the node is disconnected
    if (node.getPrevious() != null) {
        node.getPrevious().setNext(null);
    }

    // After modifying the pointers, set the current node as null to disconnect it from the list
    node.setPrevious(null);
    node.setNext(null);

