    }

    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        if (str.charAt(i) == leadingCharacter) {
            continue;
        }
        sb.append(str.charAt(i));
    }
    return sb.toString();
}

