private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null || prefix == null) {
        return null;
    }
    if (prefix.isEmpty()) {
        return true; // An empty prefix matches any string
    }

    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    } else {
        return str.startsWith(prefix);
    }
}

public static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
  if (str == null || prefix == null) {
    return true;
  }

  if (ignoreCase) {
    str = str.toLowerCase();
    prefix = prefix.toLowerCase();
  }

  return str.startsWith(prefix);
}

public static boolean startsWith(final String str,final String prefix,final boolean ignoreCase){
    if(str == null || prefix == null) 
        return str == prefix; 

    if(!ignoreCase)
        return str.startsWith(prefix);

    // Perform case-insensitive prefix matching
    if(str.length() >= prefix.length()) {
        for(int i = 0; i < prefix.length(); ++i) {
            if(str.charAt(i + str.length() - prefix.length()) != Character.toUpperCase(prefix.charAt(i)))
                return false;
        }
    } else {
        for(int i = prefix.length(); str.length() >= i; ++i) {
            if(str.charAt(str.length() - i) != Character.toUpperCase(prefix.charAt(i - prefix.length())))
                return false;
        }
    }

    return true;
}

public static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    return ignoreCase ? str != null && prefix != null && str.toLowerCase().startsWith(prefix.toLowerCase()) : str != null && str.startsWith(prefix);
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null || prefix == null) {
        return false;
    }
    if (ignoreCase) {
        str = str.toLowerCase();
        prefix = prefix.toLowerCase();
    }
    return str.startsWith(prefix);
}

