private boolean propertyIsWritable(Object key) {
    Field field;
    try {
        field = getClass().getDeclaredField(getClass().getName() + "." + key);
        field.setAccessible(true);
        return field.isWriteable();
    } catch (NoSuchFieldException | IllegalAccessException e) {
        return false;
    }
}

