public class SeparatorCalculator {
    private final Graph graph;

    public SeparatorCalculator(Graph graph) {
        this.graph = graph;
    }

    public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparators = new ArrayList<>();

        for (Edge edge : graph.getEdges()) {
            List<List<Pair<Integer, Integer>>> neighborhoodSeparators = computeNeighborhoodSeparators(edge);
            globalSeparators.addAll(neighborhoodSeparators);
        }

        return globalSeparators;
    }

    private List<List<Pair<Integer, Integer>>> computeNeighborhoodSeparators(Edge edge) {
        List<List<Pair<Integer, Integer>>> neighborhoodSeparators = new ArrayList<>();
        Set<E> visited = new HashSet<>();

        // Using DFS to explore the neighborhood
        DFSVisit(graph, edge, visited, neighborhoodSeparators);

        // Shrink the neighborhood to get minimal separators
        List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparators = new ArrayList<>();
        for (List<Pair<Integer, Integer>> neighborhood : neighborhoodSeparators) {
            List<Pair<Integer, Integer>> minimalSeparator = computeMinimalSeparator(neighborhood);
            minimalSeparators.add(new Pair<>(minimalSeparator, edge));
        }

        return minimalSeparators;
    }

    private void DFSVisit(Graph graph, Edge edge, Set<E> visited, List<List<Pair<Integer, Integer>>> neighborhoodSeparators) {
        if (visited.contains(edge)) {
            return;
        }

        visited.add(edge);
        addEdgeToNeighborhoodSeparators(neighborhoodSeparators, edge);

        // Explore the neighbors
        Set<Edge> neighbors = new HashSet<>();
        for (Edge neighbor : graph.getNeighbors(edge)) {
            if (!visited.contains(neighbor)) {
                neighbors.add(neighbor);
            }
        }

        for (Edge neighbor : neighbors) {
            DFSVisit(graph, neighbor, visited, neighborhoodSeparators);
        }
    }

    private List<Pair<Integer, Integer>> computeMinimalSeparator(List<Pair<Integer, Integer>> neighborhood) {
        if (neighborhood.isEmpty()) {
            return new ArrayList<>();
        }

        int minSize = Integer.MAX_VALUE;
        List<Pair<Integer, Integer>> minimalSeparator = new ArrayList<>();

        for (Pair<Integer, Integer> pair : neighborhood) {
            int size = pair.getValue1() + pair.getValue2();
            if (size < minSize) {
                minSize = size;
                minimalSeparator = new ArrayList<Pair<Integer, Integer>>();
                minimalSeparator.add(pair);
            } else if (size == minSize) {
                minimalSeparator.add(pair);
            }
        }

        Collections.sort(minimalSeparator, new Comparator<Pair<Integer, Integer>>() {
            @Override
            public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
                return Integer.compare(o1.getValue2(), o2.getValue2());
            }
        });

        return minimalSeparator;
