public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    for (V vertex : vertices) {
        Set<E> incidentEdges = graph.incidentEdges(vertex);
        // Check if every neighbor of the vertex is in the vertices set
        if (incidentEdges.stream()
                .noneMatch(edge -> !vertices.contains(graph.other(edge, vertex)))) {
            return false;
        }
    }
    return true;
}

public <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty set trivially forms a clique.
    }

    Vertex<V,E> firstVertex = vertices.stream().findFirst().get();
    Set<Edge<V,E>> edgesToCompare = new HashSet<>();

    for (Vertex<V,E> vertex : vertices) {
        Edges.EdgeSet<V,E> vertexEdges = graph.edgesOf(vertex);
        for (Edge<V,E> edge : vertexEdges) {
            Edges.VertexSet<V,E> edgeVertices = edge.vertices();
            if (!edgeVertices.contains(vertex) && !edgeVertices.contains(firstVertex)) {
                // The edge does not connect to either of the vertices in the subgraph.
                edgesToCompare.add(edge);
            }
        }
    }

    return edgesToCompare.isEmpty(); // If edgesToCompare is empty, the subgraph is complete.
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the number of vertices in the induced subgraph is equal to the total number of vertices in the graph
    if (vertices.size() != graph.vertices().size()) {
        return false;
    }

    // Iterate through each pair of vertices in the induced subgraph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            // Check if the vertices are not adjacent
            if (graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

