    StringBuilder newPath = new StringBuilder(pathLen + relPathLen);

    while (pos < relPathLen && pathLen > 0) {
        char forMove = relativePath.charAt(pos++);
        if (fromMove == '/') {
            continue;
        }
        switch (forMove) {
            case '.':
                if (pos < relPathLen && relativePath.charAt(pos) == '/') {
                    pos++;
                } else if (pos == relPathLen || (pos + 1) < relPathLen && relativePath.charAt(pos + 1) == '.') {
                    // Duplicate dots in the relative path
                    for (int i = pos; i < relPathLen; i++) {
                        if (relativePath.charAt(i) != '.') {
                            break;
                        }
                        pos++;
                    }
                } else {
                    // Forward slash at end of relative path which means we need to go up a directory
                    if (--pathLen > 0 && (path.charAt(pathLen - 1) == '/' || path.charAt(pathLen - 1) == ':')) {
                        if (--pathLen < 0) {
                            break;
                        }
                    }
                }
                break;
            case '..':
                if (--pathLen > 0 && (path.charAt(pathLen - 1) == '/' || path.charAt(pathLen - 1) == ':')) {
                    if (--pathLen < 0) {
                        break;
                    }
                }
                break;
            default:
                pathLen--;
                newPath.append(forMove);
                break;
        }
    }

    // Add the remaining part of the original path
    while (pathLen > 0) {
        pathLen--;
        newPath.append(path.charAt(pathLen));
    }

    return newPath.toString();
}

