    int lastSeparatorIndex = filename.lastIndexOf('.');
    if (lastSeparatorIndex == -1) {
        return -1;
    }

    int lastIndexOfDirectorySeparator = filename.lastIndexOf(File.separatorChar);
    if (lastIndexOfDirectorySeparator >= lastSeparatorIndex) {
